const inp = $('📥 Recibir Datos Medio').first().json;
const binary = $input.first().binary;

// Get base64 from binary data
const binaryKey = Object.keys(binary || {})[0] || 'data';
const fileData = binary?.[binaryKey];
const base64 = fileData?.data || '';
const mimeType = inp.mime_type || fileData?.mimeType || 'application/octet-stream';
const filename = inp.filename || fileData?.fileName || 'archivo';
const caption = inp.caption || '';
const geminiKey = inp.gemini_api_key || $vars.GEMINI_API_KEY || '';
const convertApiKey = inp.convert_api_key || '';

// Classify type
let mediaCategory;
if (mimeType.startsWith('image/')) {
  mediaCategory = 'image';
} else if (mimeType.startsWith('audio/') || mimeType.startsWith('video/ogg')) {
  mediaCategory = 'audio';
} else if (mimeType === 'application/pdf') {
  mediaCategory = 'pdf';
} else if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'application/vnd.ms-excel'].includes(mimeType)) {
  // Excel se procesa localmente en n8n (extractFromFile), sin API externa —
  // separado de 'office' (Word/PowerPoint), que sigue necesitando ConvertAPI.
  mediaCategory = 'excel';
} else if (['application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'application/msword',
            'application/vnd.openxmlformats-officedocument.presentationml.presentation'
           ].includes(mimeType)) {
  mediaCategory = 'office';
} else if (mimeType.startsWith('video/')) {
  mediaCategory = 'video';
} else {
  mediaCategory = 'unknown';
}

const media_id = inp.media_id || '';
const phone_number_id = inp.phone_number_id || '';

return [{ json: { base64, mimeType, filename, caption, mediaCategory, geminiKey, convertApiKey, media_id, phone_number_id }, binary }];

const transcripcion = ($input.first().json.body || $input.first().json || '').toString().trim();
const texto = `[Audio transcrito]: ${transcripcion}`;
return [{ json: {
  texto,
  media_ref: { type: 'audio', transcripcion },
  media_type: 'audio'
}}];

const d = $input.first().json;
const caption = d.caption ? `El cliente adjuntó este texto con la imagen: "${d.caption}". ` : '';
const prompt = `${caption}Eres el asistente de ventas Marco de Crating Express (empresa de embalaje industrial en Miami). Analiza esta imagen enviada por un cliente y extrae toda la información relevante para una cotización de embalaje: describe el objeto/artículo visible, sus dimensiones aproximadas si son visibles, materiales, estado, cualquier texto o etiqueta relevante, y cualquier detalle que ayude a cotizar un cajón o embalaje de madera. Sé específico y práctico.`;

let proxyUrl;
try {
  const tgUrl = $('🔧 TG: Construir URL Descarga').first().json.file_url;
  proxyUrl = tgUrl || `https://n8n.mdarthurdigital.com/webhook/media-proxy-g54?media_id=${encodeURIComponent(d.media_id)}&phone_number_id=${encodeURIComponent(d.phone_number_id)}&secret=REDACTED_AGENT_TOKEN`;
} catch (e) {
  proxyUrl = `https://n8n.mdarthurdigital.com/webhook/media-proxy-g54?media_id=${encodeURIComponent(d.media_id)}&phone_number_id=${encodeURIComponent(d.phone_number_id)}&secret=REDACTED_AGENT_TOKEN`;
}

const body = {
  model: 'google/gemma-4-26b-a4b-it:free',
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: prompt },
      { type: 'image_url', image_url: { url: proxyUrl } }
    ]
  }],
  temperature: 0.2,
  max_tokens: 800
};

return [{ json: { body: JSON.stringify(body), mimeType: d.mimeType, caption: d.caption } }];

const resp = $input.first().json;
const descripcion = resp.choices?.[0]?.message?.content || 'No se pudo analizar la imagen.';
const caption = $('🔧 Preparar Body Imagen').first().json.caption || '';
const captionExtra = caption ? ` El cliente escribió: "${caption}".` : '';
const texto = `[Imagen recibida]:${captionExtra} ${descripcion}`;
return [{ json: {
  texto,
  media_ref: { type: 'image', descripcion },
  media_type: 'image'
}}];

const resp = $input.first().json;
const inp = $('🔧 Leer Binario y Tipo').first().json;
const filename = inp.filename || 'documento.pdf';

let contenido = (resp.text || '').trim().slice(0, 3000);
if (!contenido) {
  contenido = 'No se pudo extraer el contenido del documento.';
}

const texto = `[Documento PDF recibido: ${filename}]: ${contenido}`;
return [{ json: {
  texto,
  media_ref: { type: 'document', filename, contenido },
  media_type: 'document'
}}];

const resp = $input.first().json;
const inp = $('🔧 Leer Binario y Tipo').first().json;
const filename = inp.filename || 'documento';

// ConvertAPI response: { Files: [{ FileData: 'base64txt' }] }
let contenido = '';
try {
  const fileData = resp.Files?.[0]?.FileData || '';
  if (fileData) {
    contenido = Buffer.from(fileData, 'base64').toString('utf8').slice(0, 3000);
  }
} catch(e) {}

if (!contenido) {
  contenido = 'No se pudo extraer el contenido del documento.';
}

const texto = `[Documento Office recibido: ${filename}]: ${contenido}`;
return [{ json: {
  texto,
  media_ref: { type: 'document', filename, contenido },
  media_type: 'document'
}}];

const inp = $('🔧 Leer Binario y Tipo').first().json;
const tipo = inp.mediaCategory === 'video' ? 'video' : 'archivo';
const texto = tipo === 'video'
  ? '[Video recibido]: El cliente envió un video. Por el momento no puedo analizar videos directamente. Si contiene información sobre las dimensiones o el artículo a embalar, por favor descríbelo en un mensaje de texto.'
  : `[Archivo recibido: ${inp.filename || 'archivo'}]: El cliente envió un archivo en formato no soportado (${inp.mimeType}). Por favor pídele que lo envíe en PDF o imagen.`;
return [{ json: {
  texto,
  media_ref: { type: tipo, filename: inp.filename },
  media_type: tipo
}}];

const d = $input.first().json;
return [{ json: {
  texto: d.texto || '[Medio recibido pero no procesado]',
  media_ref: d.media_ref || {},
  media_type: d.media_type || 'unknown'
}}];

const resp = $input.first().json;
const filePath = resp?.result?.file_path;
const BOT_TOKEN = 'REDACTED_TELEGRAM_BOT_TOKEN';
const fileUrl = filePath ? `https://api.telegram.org/file/bot${BOT_TOKEN}/${filePath}` : '';
return [{ json: { file_url: fileUrl } }];

const rows = $input.all().map(i => i.json);
const inp = $('🔧 Leer Binario y Tipo').first().json;
const filename = inp.filename || 'documento.xlsx';

let contenido = '';
if (rows.length > 0) {
  contenido = rows.slice(0, 30).map(r => Object.entries(r).map(([k,v]) => `${k}: ${v}`).join(', ')).join('\n');
} else {
  contenido = 'No se pudo extraer el contenido de la hoja de cálculo.';
}
contenido = contenido.slice(0, 3000);

const texto = `[Documento Excel recibido: ${filename}]: ${contenido}`;
return [{ json: {
  texto,
  media_ref: { type: 'document', filename, contenido },
  media_type: 'document'
}}];

const b = $input.first().binary.data;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const renamed = await this.helpers.prepareBinaryData(buf, 'archivo.zip', 'application/zip');
return [{ json: $input.first().json, binary: { data: renamed } }];

const inp = $('🔧 Leer Binario y Tipo').first().json;
const filename = inp.filename || 'documento';
const binary = $input.first().binary || {};
const keys = Object.keys(binary);

let contenido = '';
try {
  const docKey = keys.find(k => (binary[k].fileName || '') === 'document.xml');
  const slideKeys = keys.filter(k => /^slide\d+\.xml$/.test(binary[k].fileName || ''))
    .sort((a, b) => parseInt(binary[a].fileName.match(/\d+/)[0]) - parseInt(binary[b].fileName.match(/\d+/)[0]));

  if (docKey) {
    // Word: texto en <w:t>
    const buf = await this.helpers.getBinaryDataBuffer(0, docKey);
    const xml = buf.toString('utf8');
    const matches = [...xml.matchAll(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g)];
    contenido = matches.map(m => m[1]).join(' ');
  } else if (slideKeys.length > 0) {
    // PowerPoint: texto en <a:t>, una diapositiva por archivo
    const partes = [];
    for (const key of slideKeys) {
      const buf = await this.helpers.getBinaryDataBuffer(0, key);
      const xml = buf.toString('utf8');
      const matches = [...xml.matchAll(/<a:t>([\s\S]*?)<\/a:t>/g)];
      partes.push(matches.map(m => m[1]).join(' '));
    }
    contenido = partes.join('\n');
  }
  contenido = contenido
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .trim().slice(0, 3000);
} catch (e) {}

if (!contenido) {
  contenido = 'No se pudo extraer el contenido del documento.';
}

const texto = `[Documento Office recibido: ${filename}]: ${contenido}`;
return [{ json: {
  texto,
  media_ref: { type: 'document', filename, contenido },
  media_type: 'document'
}}];

